SOURCE_V2 = "import csv, json, sys\nfrom decimal import Decimal, InvalidOperation, localcontext\ndef exact_add(a, b):\n    with localcontext() as ctx:\n        ctx.prec = max(a.adjusted(), b.adjusted()) - min(a.as_tuple().exponent, b.as_tuple().exponent) + 3\n        return a + b\ndef summarize(path):\n    total = Decimal('0'); count = 0; groups = {}\n    with open(path, encoding='utf-8-sig', newline='') as f:\n        reader = csv.DictReader(f)\n        if not reader.fieldnames or 'amount' not in reader.fieldnames:\n            raise ValueError('amount column required')\n        for row in reader:\n            amount = Decimal(row['amount'])\n            if not amount.is_finite(): raise ValueError('nonfinite amount')\n            total = exact_add(total, amount); count += 1\n            category = row.get('category', '')\n            groups[category] = exact_add(groups.get(category, Decimal('0')), amount)\n    result = {'total': str(total), 'rows': count}\n    result['categories'] = {k: str(v) for k,v in sorted(groups.items())}\n    return result\nif __name__ == '__main__':\n    try:\n        print(json.dumps(summarize(sys.argv[1]), ensure_ascii=False, sort_keys=True))\n    except (OSError, ValueError, InvalidOperation, IndexError, TypeError) as exc:\n        print(str(exc), file=sys.stderr); sys.exit(2)\n"
SOURCE_V1 = SOURCE_V2.replace("    result['categories'] = {k: str(v) for k,v in sorted(groups.items())}\n", "")

def task(project="csv-pilot", task_id="create-1", mode="CREATE", base=None, seconds=30):
    value={"project_id":project,"task_id":task_id,"mode":mode,"request":"CSV exact totals and categories" if mode=="UPDATE" else "CSV exact total and rows","files":{"summary.py":SOURCE_V2 if mode=="UPDATE" else SOURCE_V1},"oracle_version":"csv-v2" if mode=="UPDATE" else "csv-v1","deadline_seconds":seconds}
    if mode=="CREATE":value["files"]["README.md"]="Run python summary.py input.csv; amount column required.\n"
    if base:value["base_sha256"]=base
    return value
